#include <vector>
#include <queue>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long subtreeInversionSum(std::vector<std::vector<int>>& edges, std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<std::vector<int>> g(n);
        for (const auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        long long baseSum = 0;
        for (int x : nums) baseSum += x;
        std::vector<std::vector<int>> treeAdj(n);
        std::vector<bool> visited(n, false);
        visited[0] = true;
        std::queue<int> q;
        q.push(0);
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            for (int nxt : g[curr]) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    treeAdj[curr].push_back(nxt);
                    q.push(nxt);
                }
            }
        }

        auto getSubtree = [&](auto& self, int u, std::vector<int>& nodes) -> void {
            nodes.push_back(u);
            for (int v : treeAdj[u]) self(self, v, nodes);
        };

        long long ans = baseSum;
        for (int u = 0; u < n; ++u) {
            std::vector<int> subNodes;
            getSubtree(getSubtree, u, subNodes);
            long long subSum = 0;
            for (int x : subNodes) subSum += nums[x];
            ans = std::max(ans, baseSum - 2 * subSum);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long subtreeInversionSum(int[][] edges, int[] nums, int k) {
        int n = nums.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        long baseSum = 0;
        for (int x : nums) baseSum += x;
        List<List<Integer>> treeAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) treeAdj.add(new ArrayList<>());
        boolean[] visited = new boolean[n];
        visited[0] = true;
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        while (!q.isEmpty()) {
            int curr = q.poll();
            for (int nxt : g.get(curr)) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    treeAdj.get(curr).add(nxt);
                    q.offer(nxt);
                }
            }
        }
        long ans = baseSum;
        for (int u = 0; u < n; u++) {
            List<Integer> subNodes = new ArrayList<>();
            getSubtree(u, treeAdj, subNodes);
            long subSum = 0;
            for (int x : subNodes) subSum += nums[x];
            ans = Math.max(ans, baseSum - 2 * subSum);
        }
        return ans;
    }

    private void getSubtree(int u, List<List<Integer>> treeAdj, List<Integer> subNodes) {
        subNodes.add(u);
        for (int v : treeAdj.get(u)) getSubtree(v, treeAdj, subNodes);
    }
}

